using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — strongly-typed metadata access
JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
}

// Now demonstrate the "not available" path:
// Use a custom context that only knows about Person, not about int.
var restricted = new JsonSerializerOptions { TypeInfoResolver = new PersonOnlyContext() };

if (restricted.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
{
    Console.WriteLine($"Unexpected: got info for int");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> returned false — metadata not available (no exception thrown)");
}

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

